def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    """Calculate the maximum sum of values collected on two non-overlapping paths
    from the top-left to the bottom-right corner of an N x N grid."""
    # Build the grid
    grid = [[0] * N for _ in range(N)]
    for x, y, v in grid_values:
        if x == 0 and y == 0 and v == 0:
            break
        # convert to 0-based indices
        grid[x - 1][y - 1] = v

    # Edge case: single cell
    if N == 1:
        return grid[0][0]

    INF_NEG = -10 ** 15
    # dp[i1][i2] = max score at step s when person A at row i1, person B at row i2
    dp = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[0][0]      # start at (1,1)

    # Total steps from (1,1) to (N,N) is 2*N - 2 moves, number of positions visited is 2*N - 1
    # We use step = i1 + j1 = i2 + j2, ranging from 2 to 2*N
    for step in range(2, 2 * N + 1):
        new_dp = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
        i_min = max(1, step - N)
        i_max = min(N, step - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = step - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = step - i2
                if j2 < 1 or j2 > N:
                    continue
                best = INF_NEG
                # Consider the four previous moves: (stay, move down) combinations
                for di1 in (0, -1):
                    for di2 in (0, -1):
                        pi1, pi2 = i1 + di1, i2 + di2
                        if pi1 < 1 or pi2 < 1:
                            continue
                        val = dp[pi1][pi2]
                        if val > best:
                            best = val
                if best == INF_NEG:
                    continue
                add = grid[i1 - 1][j1 - 1]
                if i1 != i2 or j1 != j2:
                    add += grid[i2 - 1][j2 - 1]
                new_dp[i1][i2] = best + add
        dp = new_dp

    return dp[N][N]

