def preorder_traversal(inorder: str, postorder: str) -> str:
    """Reconstruct a binary tree from inorder and postorder traversals and
    return its preorder traversal as a string."""
    if not inorder or not postorder:
        return ''
    idx_map = {c: i for i, c in enumerate(inorder)}

    def helper(in_start: int, in_end: int, post_start: int, post_end: int) -> str:
        if in_start > in_end or post_start > post_end:
            return ''
        root = postorder[post_end]
        in_root_idx = idx_map[root]
        left_size = in_root_idx - in_start
        left = helper(in_start, in_root_idx - 1,
                      post_start, post_start + left_size - 1)
        right = helper(in_root_idx + 1, in_end,
                       post_start + left_size, post_end - 1)
        return root + left + right

    return helper(0, len(inorder) - 1, 0, len(postorder) - 1)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Breadth-First Search up to 10 steps. Return minimum steps or "NO ANSWER!" if impossible.
    """
    if A == B:
        return 0

    max_steps = 10
    visited = {A}
    queue = [(A, 0)]

    while queue:
        current, steps = queue.pop(0)
        if steps >= max_steps:
            continue

        next_steps = steps + 1
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_string = current[:idx] + tgt + current[idx + len(src):]
                if new_string == B:
                    return next_steps
                if new_string not in visited:
                    visited.add(new_string)
                    queue.append((new_string, next_steps))
                start = idx + 1  # look for next overlapping occurrence

    return "NO ANSWER!"

