                merged.append([start, end])
    # Sum total cleared length
    cleared = sum(end - start for start, end in merged)
    # Ensure not negative result
    return max(0, l - cleared)

def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    """Return the number of trees left on a road of length l after clearing specified areas."""
    if l <= 0:
        return 0

    # Clamp and sort intervals
    intervals = []
    for a, b in areas:
        start = max(0, min(a, l))
        end = max(0, min(b, l))
        if start < end:
            intervals.append((start, end))
    if not intervals:
        return l

    intervals.sort(key=lambda x: x[0])

    total_removed = 0
    cur_start, cur_end = intervals[0]
    for start, end in intervals[1:]:
        if start <= cur_end:  # overlap
            cur_end = max(cur_end, end)
        else:
            total_removed += cur_end - cur_start
            cur_start, cur_end = start, end
    total_removed += cur_end - cur_start

    remaining = l - total_removed
    return remaining if remaining > 0 else 0

