    :return: The maximum total value of herbs that can be picked within the time limit.
    """
    # DP array where dp[t] represents the maximum value achievable with time at most t
    dp = [0] * (T + 1)

    for time, value in herbs:
        if time > T:
            continue  # cannot pick this herb due to time constraint
        # iterate backwards to avoid using the same herb multiple times
        for t in range(T, time - 1, -1):
            new_val = dp[t - time] + value
            if new_val > dp[t]:
                dp[t] = new_val

    return max(dp)

