        for i in range(1, m + 1):
            prefix[i] = (prefix[i - 1] + dp[i]) % MOD
        new_dp = [0] * (m + 1)
        for j in range(m + 1):
            left = j - ai - 1
            if left >= 0:
                val = prefix[j] - prefix[left]
