def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1
    for i in range(n):
        limit = a[i]
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for j in range(1, m + 1):
            prefix[j] = (prefix[j-1] + dp[j]) % MOD
        new_dp = [0] * (m + 1)
        for j in range(m + 1):
            low = j - limit
            if low <= 0:
                val = prefix[j]
            else:
                val = (prefix[j] - prefix[low-1]) % MOD
            new_dp[j] = val
        dp = new_dp
    return dp[m] % MOD

